/**
 * LIVE CALIBRATION CORPUS BENCH — scales the single-battle calibration
 * (liveSelfCalibration.test.ts) from ONE hand-made fixture to the whole
 * drained replay archive.
 *
 * The fixture (`__fixtures__/calib-corpus.ndjson`) is ONE LiveSelfStream
 * JSON per line — the settled decode of every archive member that fully
 * decodes, in content-address (sha) order, regenerated by the maintainer
 * CLI:
 *
 *   cargo run -p replay-corpus -- calib \
 *     --archive <drained archive> \
 *     --out <webui>/src/features/replay/__fixtures__/calib-corpus.ndjson
 *
 * It is NOT committed (real battle streams; the whole __fixtures__ dir is
 * gitignored). The test skips when the file is absent (fresh clones, CI),
 * mirroring the single-battle calibration's skip-when-absent pattern.
 *
 * Pass/fail rule (strict, the single-battle bar): for EVERY battle whose
 * stream carries the authoritative BattleResults payload, the buildSelfStats
 * ESTIMATE — run with battleResults STRIPPED so the post-battle merge cannot
 * overwrite it, i.e. exactly what the live view shows mid-battle — must sit
 * within the shared calibration tolerances (liveSelfStats.ts) of the
 * authoritative figures for damage, hits, kills and damage taken. ANY
 * exceeding battle fails the bench: attribution regressed on real data, and
 * the failure output lists the fixture line numbers. Battles WITHOUT the
 * payload (Lesta recordings carry none at all — see the single-battle
 * test's note) cannot be compared and are only counted in the printed
 * summary; a battle whose self identity fails to resolve always fails.
 *
 * LEDGER INVARIANT (the 2026-10 regression pin): the per-target ledgers
 * are a CLAIM PARTITION of the hulls' HP-loss timelines — every drop is
 * credited once, split across its covering impacts. The old per-impact
 * walk re-credited the full window delta per shell event and per
 * attacker, summing the dealt rows to a 2.4x median of the results
 * screen and the received rows to 7.7x (worst 13.8x). The bench
 * therefore hard-pins, for EVERY resolved battle: neither ledger may
 * exceed the gross HP loss it partitions (with rounding slack) — a
 * breach means the partition double-counts again. Estimate-grade drift
 * against the authoritative figures stays a printed summary (DoT is
 * invisible to impacts; healed-back hulls read gross loss above the
 * server's net damage taken), not a hard rule.
 *
 * Known authority gap, for review context when a line trips: the hits
 * comparison's authoritative side is the ribbon total (main + secondary +
 * torpedo + depth-charge hits); aircraft rockets and bombs have NO
 * authoritative counter in the public results array, so recorder battles
 * that landed them read an over-estimate drift that is a data-source gap,
 * not an attribution regression.
 */
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";

import type { HpSample, LiveSelfStream, VehicleEntry } from "@/api";
import { parsePostBattle, type PostBattlePlayer } from "./postBattle";
import {
  CALIB_DAMAGE_TOL,
  CALIB_FRAGS_TOL,
  CALIB_HITS_TOL,
  CALIB_TAKEN_TOL,
  buildSelfStats,
} from "./liveSelfStats";

// Resolved from the package root (vitest runs under node with cwd =
// packages/webui, the same process.cwd() convention renderSample.test.ts
// uses; the webui tsconfig carries no node types, so the small node:fs /
// node:path surface is declared in src/overlay/sample-artifact.d.ts).
const FIXTURE = join(
  process.cwd(),
  "src",
  "features",
  "replay",
  "__fixtures__",
  "calib-corpus.ndjson",
);

/** The battle's roster, derived from the arena join exactly the way the
 * single-battle calibration test feeds buildSelfStats. */
function rosterOf(stream: LiveSelfStream): VehicleEntry[] {
  return (stream.arenaPlayers ?? []).map(
    (p): VehicleEntry => ({
      id: p.playerId ?? 0,
      name: p.name ?? "",
      relation: p.isSelf ? 0 : p.teamId === 0 ? 1 : 2,
      shipId: p.shipParamsId ?? 0,
    }),
  );
}

/** A hull's gross HP loss across its whole timeline — every downward
 *  step summed, heals ignored (the budget the claim partition may
 *  never exceed). */
function grossHpLoss(hp: HpSample[] | undefined): number {
  if (!hp || hp.length < 2) return 0;
  let sum = 0;
  for (let i = 1; i < hp.length; i++) {
    const d = hp[i - 1].value - hp[i].value;
    if (d > 0) sum += d;
  }
  return sum;
}

/** The authoritative direct-hit counter: the ribbon families with an
 * authoritative per-player total (see postBattle.ts RIBBON_SOURCES). */
function authoritativeHits(p: PostBattlePlayer): number {
  const ribbon = (key: string): number => p.ribbons.find((r) => r.key === key)?.value ?? 0;
  return (
    ribbon("main_caliber") +
    ribbon("secondary_caliber") +
    ribbon("torpedo") +
    ribbon("dbomb")
  );
}

/** One compared metric: its tolerance and the accumulated error
 * distribution the bench prints at the end. */
class MetricBench {
  within = 0;
  compared = 0;
  maxDrift = 0;
  /** (drift, line) — the worst offenders, sorted at print time. */
  private readonly worst: [number, number][] = [];

  constructor(
    readonly label: string,
    readonly tolerance: number,
  ) {}

  /** Record one battle's |estimate − authority| drift; true when within
   * the tolerance. */
  record(line: number, drift: number): boolean {
    this.compared++;
    this.maxDrift = Math.max(this.maxDrift, drift);
    this.worst.push([drift, line]);
    if (drift <= this.tolerance) {
      this.within++;
      return true;
    }
    return false;
  }

  /** The summary line: coverage, max drift and the worst fixture lines. */
  summary(): string {
    const top = [...this.worst]
      .sort((a, b) => b[0] - a[0])
      .slice(0, 3)
      .map(([d, line]) => `#${line} (drift ${Math.round(d)})`)
      .join(", ");
    return `${this.label}: ${this.within}/${this.compared} within ±${this.tolerance}, max drift ${Math.round(this.maxDrift)}, worst ${top || "—"}`;
  }
}

describe("live calibration corpus bench vs the drained archive", () => {
  it("estimates every battle within the single-battle tolerances", () => {
    if (!existsSync(FIXTURE)) {
      console.warn("calibration corpus absent — regenerate with `replay-corpus calib`");
      return;
    }
    const lines = readFileSync(FIXTURE, "utf8")
      .split("\n")
      .filter((l) => l.trim().length > 0);
    if (lines.length === 0) {
      console.warn("calibration corpus is empty — regenerate with `replay-corpus calib`");
      return;
    }

    const damage = new MetricBench("damage", CALIB_DAMAGE_TOL);
    const hits = new MetricBench("hits", CALIB_HITS_TOL);
    const kills = new MetricBench("kills", CALIB_FRAGS_TOL);
    const taken = new MetricBench("damage taken", CALIB_TAKEN_TOL);
    /** Estimate-grade ledger drift against the authority (ratios, print
     *  only — see the header's LEDGER INVARIANT note for the hard rule). */
    const dealtRatios: number[] = [];
    const recvRatios: number[] = [];
    const violations: string[] = [];
    let withAuthority = 0;
    let noAuthority = 0;

    lines.forEach((line, idx) => {
      const lineNo = idx + 1;
      const stream = JSON.parse(line) as LiveSelfStream;
      // The ESTIMATE: the same pipeline the single-battle test runs, with
      // the authoritative payload stripped so mergeFinal cannot overwrite
      // the live estimate being benched.
      const m = buildSelfStats({
        stream: { ...stream, battleResults: null },
        roster: rosterOf(stream),
        dataLang: "zh-CN",
      });
      if (m == null || m.selfEntityId == null) {
        violations.push(`line ${lineNo}: self identity unresolved (model=${m == null ? "null" : "no self entity"})`);
        return;
      }
      // ── LEDGER INVARIANT (every resolved battle): the ledgers are a
      // claim partition of the hulls' gross HP loss — totals beyond that
      // budget mean lost HP is being counted more than once.
      const dealtSum = m.dealt.reduce((s, r) => s + r.damage, 0);
      const recvSum = m.received.reduce((s, r) => s + r.damage, 0);
      const budgetAll = stream.trajectories.reduce((s, t) => s + grossHpLoss(t.hpSamples), 0);
      const budgetSelf = grossHpLoss(
        stream.trajectories.find((t) => t.entityId === m.selfEntityId)?.hpSamples,
      );
      if (dealtSum > budgetAll * 1.05 + 200) {
        violations.push(
          `line ${lineNo}: dealt ledger ${Math.round(dealtSum)} exceeds the hulls' gross HP loss ${Math.round(budgetAll)} — the claim partition double-counts`,
        );
      }
      if (recvSum > budgetSelf * 1.05 + 200) {
        violations.push(
          `line ${lineNo}: received ledger ${Math.round(recvSum)} exceeds my hull's gross HP loss ${Math.round(budgetSelf)} — the claim partition double-counts`,
        );
      }
      // The AUTHORITY: the stream's own BattleResults payload. Self joins
      // in the same order mergeFinal uses (accountDBID, then the model's
      // player id, then the name).
      const post = parsePostBattle(stream.battleResults ?? null);
      const self =
        post == null
          ? null
          : (post.selfId != null ? post.players.find((p) => p.accountId === post.selfId) : undefined) ??
            (m.selfPlayerId != null ? post.players.find((p) => p.accountId === m.selfPlayerId) : undefined) ??
            (m.selfName != null ? post.players.find((p) => p.name === m.selfName) : undefined) ??
            null;
      if (self == null) {
        // Lesta recordings carry no 0x22 payload at all — nothing to
        // compare against; exercise happened, authority did not.
        noAuthority++;
        return;
      }
      withAuthority++;
      const checks: [MetricBench, number, number, string][] = [
        [damage, m.damage, self.damage, `damage ${m.damage} vs authoritative ${self.damage}`],
        [hits, m.hits, authoritativeHits(self), `hits ${m.hits} vs authoritative ${authoritativeHits(self)}`],
        [kills, m.frags, self.frags, `kills ${m.frags} vs authoritative ${self.frags}`],
        [taken, m.taken, self.damageTaken, `damage taken ${m.taken} vs authoritative ${self.damageTaken}`],
      ];
      if (self.damage > 0) dealtRatios.push(dealtSum / self.damage);
      if (self.damageTaken > 0) recvRatios.push(recvSum / self.damageTaken);
      for (const [bench, estimate, authority, detail] of checks) {
        const drift = Math.abs(estimate - authority);
        if (!bench.record(lineNo, drift)) {
          violations.push(
            `line ${lineNo}: ${detail} — drift ${Math.round(drift)} exceeds ±${bench.tolerance}`,
          );
        }
      }
    });

    const ratioLine = (label: string, xs: number[]): string => {
      if (xs.length === 0) return `  ${label}: —`;
      const sorted = [...xs].sort((a, b) => a - b);
      const med = sorted[Math.floor(sorted.length / 2)]!;
      return `  ${label}: median ${med.toFixed(2)}x, max ${sorted[sorted.length - 1]!.toFixed(2)}x of ${xs.length}`;
    };
    console.log(
      `[calib-corpus] ${lines.length} battle(s): ${withAuthority} compared against BattleResults, ` +
        `${noAuthority} without an authoritative payload (Lesta)\n` +
        [damage, hits, kills, taken].map((b) => `  ${b.summary()}`).join("\n") +
        "\n" +
        ratioLine("dealt ledger / authority damage", dealtRatios) +
        "\n" +
        ratioLine("received ledger / authority damageTaken", recvRatios),
    );
    expect(
      violations,
      `${violations.length} battle(s) exceed the calibration tolerances — attribution regressed on real data:\n` +
        violations.join("\n"),
    ).toEqual([]);
    expect(withAuthority + noAuthority).toBe(lines.length);
  });
});
